'use strict';
const KEY='my-strength-v2',LEGACY='my-strength-v1',LEGACY_DRAFT='my-strength-draft-v1',THEME_KEY='my-strength-theme-v1';
const VERSION='3.3.5 · AI beta';
const $=s=>document.querySelector(s), safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getJSON=(k,def)=>{try{return JSON.parse(localStorage.getItem(k))??def}catch{return def}};
const byId=id=>[...PROGRAMME,...OLD_PROGRAMME,...(model?.customWorkouts||[])].flatMap(w=>w.exercises).find(e=>e.id===id);
const getWorkout=id=>PROGRAMME.find(w=>w.id===id)||OLD_PROGRAMME.find(w=>w.id===id)||(model?.customWorkouts||[]).find(w=>w.id===id)||{id,name:'Previous workout',focus:'Archived programme',exercises:[]};
const initial=()=>({schema:2,sessions:[],draft:null,prefs:{theme:localStorage.getItem(THEME_KEY)||'system',restDays:1,restSeconds:90,manualNext:null,rotationAddons:[],includeOptional:false,color:'ocean',sound:true,volume:'normal',prepSeconds:5},assessments:[],customWorkouts:[],migrated:false});
let entryModal=null,audioCtx=null,timerLast={hold:null,rest:null};
let db=null,model=initial(),ui={page:'home',openWorkout:'A',guideFilter:'all',guideSearch:'',guideId:null,from:'guide',historyId:null,progressId:'squat',statPeriod:28,guideMode:'all',guideMuscle:'all',guideType:'all',progressTab:'strength',progressPickerOpen:false,monthOffset:0,customSelected:[],customName:'My custom workout',customReplace:'extra',customTarget:'A',editingCustom:null,lightbox:null},rest={end:0,remaining:0,running:false,label:''},hold={end:0,remaining:0,running:false,id:null,index:0,started:0,prep:0,total:0},saveTimer=0;
function dateOf(v){let d=new Date(v);return Number.isNaN(d.getTime())?new Date():d}
function dateShort(d){return dateOf(d).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}
function dateLong(d){return dateOf(d).toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}
function daysBetween(a,b){let d=x=>{let t=dateOf(x);return Date.UTC(t.getFullYear(),t.getMonth(),t.getDate())};return Math.round((d(b)-d(a))/86400000)}
function plusCalendarDays(v,n){let d=dateOf(v);d.setHours(12,0,0,0);d.setDate(d.getDate()+n);return d}
function now(){return Date.now()}
function sessionsSorted(){return [...model.sessions].sort((a,b)=>Number(b.date)-Number(a.date))}
function rotationList(){let addons=(model.prefs.rotationAddons||[]).filter(a=>!!cleanCustom(a.id));let out=[];for(const w of PROGRAMME){out.push(w);addons.filter(a=>a.after===w.id).forEach(a=>out.push(getWorkout(a.id)))}return out}
function newSessions(){const ids=new Set(rotationList().map(w=>w.id));return sessionsSorted().filter(s=>ids.has(s.rotationSlot||s.workout)&&!s.extra)}
function nextInfo(){let rotationLast=newSessions()[0],cycle=rotationList(),index=rotationLast?cycle.findIndex(w=>w.id===(rotationLast.rotationSlot||rotationLast.workout)):-1;let next=cycle[(index+1)%cycle.length];if(model.prefs.manualNext)next=getWorkout(model.prefs.manualNext);let last=sessionsSorted().find(s=>!s.legacy&&(PROGRAMME.some(w=>w.id===s.workout)||s.workout?.startsWith('custom-')))||rotationLast;let eligible=last?plusCalendarDays(last.date,Number(model.prefs.restDays)+1):new Date();let ready=!last||daysBetween(last.date,now())>Number(model.prefs.restDays);return {last,next,eligible,ready,rotationLast};}
function getEntries(s){return Object.entries(s?.entries||{}).flatMap(([id,arr])=>(arr||[]).filter(z=>z.done).map(z=>({id,...z}))) }
function totalSets(s){return getEntries(s).length}
function isGym(w){return w.id!=='D'}
function previousFor(id){for(let s of sessionsSorted()){let z=(s.entries||{})[id];if(z&&z.some(q=>q.done))return {s,sets:z}}return null}
function completedLoads(id){return sessionsSorted().flatMap(s=>(s.entries?.[id]||[]).filter(z=>z.done&&Number(z.weight)>0).map(z=>({date:s.date,weight:Number(z.weight),reps:Number(z.reps)||0}))).sort((a,b)=>a.date-b.date)}
function migrateLegacy(){if(model.migrated)return;let old=getJSON(LEGACY,[]);if(Array.isArray(old))for(let s of old){if(!s||!s.entries||!s.date)continue;const uid='legacy-'+String(s.id??s.date);if(!model.sessions.some(x=>x.id===uid))model.sessions.push({...s,id:uid,legacy:true});}let oldDraft=getJSON(LEGACY_DRAFT,null);if(oldDraft&&oldDraft.entries&&!model.draft){/* Retain old draft untouched: exported in safety backup, not silently reinterpreted. */}model.migrated=true;save();}
function openDb(){return new Promise((ok,err)=>{if(!('indexedDB'in window))return err(new Error('unavailable'));let r=indexedDB.open('my-strength-v2',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('app'))r.result.createObjectStore('app')};r.onsuccess=()=>ok(r.result);r.onerror=()=>err(r.error)})}
function idbRead(){return new Promise((ok,err)=>{let t=db.transaction('app','readonly').objectStore('app').get('state');t.onsuccess=()=>ok(t.result);t.onerror=()=>err(t.error)})}
function idbWrite(v){return new Promise((ok,err)=>{let tx=db.transaction('app','readwrite');tx.objectStore('app').put(v,'state');tx.oncomplete=()=>ok();tx.onerror=()=>err(tx.error)})}
function save(){const data=JSON.stringify(model);try{localStorage.setItem(KEY,data)}catch(e){note('Storage limited. Download a backup in Settings.')}if(db)idbWrite(model).catch(()=>note('Storage error; export a backup.'))}
function download(txt,name,type){const blob=new Blob([txt],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function backup(){download(JSON.stringify({app:'my-strength',version:3.3,exportedAt:new Date().toISOString(),state:model,legacyDraft:getJSON(LEGACY_DRAFT,null)},null,2),'my-strength-v3-3-5-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json')}

function exerciseLabel(id){return byId(id)?.name||model.sessions.flatMap(s=>s.exerciseSnapshots||[]).find(e=>e.id===id)?.name||id}
function csv(){const rows=[['Date','Programme','Exercise','Set','Weight kg','Reps','Hold seconds','Completed','Notes']];for(let s of sessionsSorted())for(let [id,arr] of Object.entries(s.entries||{}))arr.forEach((z,i)=>rows.push([new Date(s.date).toISOString().slice(0,10),(s.workoutName||getWorkout(s.workout).name),exerciseLabel(id),i+1,z.weight??'',z.reps??'',z.seconds??'',z.done?'Yes':'No',s.notes||'']));download(rows.map(r=>r.map(c=>'"'+String(c??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),'my-strength-v2-history.csv','text/csv;charset=utf-8')}
function note(msg){let n=$('.toast');if(n)n.remove();let x=document.createElement('div');x.className='toast';x.textContent=msg;document.body.appendChild(x);setTimeout(()=>x.remove(),3400)}
function themeApply(){let t=model.prefs.theme,dark=t==='dark'||(t==='system'&&window.matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.color=model.prefs.color||'ocean';document.documentElement.style.colorScheme=dark?'dark':'light';let m=$('meta[name="theme-color"]');if(m)m.content=dark?'#0e1623':'#f6f8fb'}
window.matchMedia?.('(prefers-color-scheme:dark)')?.addEventListener?.('change',()=>{if(model.prefs.theme==='system'){themeApply();render()}});

function library(){let dict=new Map();for(const w of [...PROGRAMME,...OLD_PROGRAMME])for(const x of w.exercises){if(!dict.has(x.id))dict.set(x.id,x)}return [...dict.values()]}
function equipment(x){let n=x.name.toLowerCase();if(x.kind==='mobility'||x.kind==='stretch')return 'Mobility / stretch';if(x.kind==='isometric')return 'Isometric';if(/run|bike|cycl/.test(n)||x.unit==='min')return 'Cardio';if(x.kind==='bodyweight'||x.unit==='reps'||n.includes('plank')||n.includes('push-up')||n.includes('pull-up')||n.includes('bird dog'))return 'Bodyweight';if(/leg press|leg curl|leg extension|calf raise/.test(n))return 'Machines';if(/kettlebell/.test(n))return 'Kettlebells';if(/cable|pulldown|face pull|pallof|triceps pushdown/.test(n))return 'Cables';if(/dumbbell|one-arm|lateral raise|curl/.test(n))return 'Dumbbells';if(/barbell|squat|romanian deadlift|bench press|hip thrust/.test(n)&&!n.includes('bulgarian'))return 'Barbell / free weights';return 'Other / mixed'}
function matchesMuscle(x,g){if(g==='all')return true;let map={'Legs':['Quads','Hamstrings','Calves','Glutes'],'Deltoids':['Shoulders','Rear shoulders'],'Arms':['Biceps','Triceps'],'Core & abs':['Core','Abs']};return (map[g]||[g]).some(m=>x.muscles.includes(m))}
function muscleGroups(all){return [...new Set(['Legs','Deltoids','Arms','Core & abs',...all.flatMap(x=>x.muscles)])].sort()}
function customOptions(){return (model.customWorkouts||[])}
function cleanCustom(id){return customOptions().find(w=>w.id===id)}
function saveCustom(){let name=($('#custom-name')?.value||ui.customName||'My custom workout').trim().slice(0,65);let ids=ui.customSelected;if(!ids.length){note('Select at least one exercise.');return}if(!name){note('Enter a workout name.');return}let lib=library();let exercises=ids.map(id=>lib.find(x=>x.id===id)).filter(Boolean).map(x=>({...x}));let id=ui.editingCustom||'custom-'+Date.now();if(model.draft?.workout===id){note('Finish or discard the current draft before editing this workout.');return}let custom={id,name,focus:'Custom programme',short:exercises.length+' selected movements',place:'Flexible',color:'#2b887f',emoji:'✦',exercises};model.customWorkouts=ui.editingCustom?customOptions().map(w=>w.id===id?custom:w):[...customOptions(),custom];ui.customSelected=[];ui.customName='My custom workout';ui.editingCustom=null;save();ui.openWorkout=id;tabTo('workout');note('Custom workout saved. Choose to add, replace or repeat it in your rolling schedule.')}
function customBuilder(){let all=library(),selected=ui.customSelected,muscles=muscleGroups(all),types=[...new Set(all.map(equipment))].sort(),filtered=all.filter(x=>(matchesMuscle(x,ui.guideMuscle))&&(ui.guideType==='all'||equipment(x)===ui.guideType)&&((x.name+' '+x.muscles.join(' ')).toLowerCase().includes(ui.guideSearch.toLowerCase())));return `<div class="kicker">MAKE IT YOURS</div><h1>${ui.editingCustom?'Edit':'Build'} custom programme</h1><p class="subtitle">Select as many exercises as you like. Save a reusable routine, then add it as an extra session or replace the next A/B/C/D workout.</p><div class="panel stack"><label class="field-label">Workout name</label><input id="custom-name" class="search" value="${safe(ui.customName)}" placeholder="My custom workout"><div class="flex-between"><b>${selected.length} selected</b><button class="small-link" data-act="customClear">Clear selection</button></div><div class="filter-pair"><label>Muscle group<select id="builder-muscle"><option value="all">All muscles</option>${muscles.map(m=>`<option ${m===ui.guideMuscle?'selected':''}>${safe(m)}</option>`).join('')}</select></label><label>Exercise type<select id="builder-type"><option value="all">All types</option>${types.map(t=>`<option ${t===ui.guideType?'selected':''}>${safe(t)}</option>`).join('')}</select></label></div><div class="search-wrap"><input type="search" autocapitalize="off" autocomplete="off" spellcheck="false" class="search" id="builder-search" placeholder="Search exercises..." value="${safe(ui.guideSearch)}"><div class="search-actions"><button type="button" class="btn secondary small" data-act="builderPrompt">Type</button><button type="button" class="btn secondary small" data-act="builderSearch">Search</button><button type="button" class="btn secondary small" data-act="builderClear">Clear</button></div></div><div class="builder-list">${filtered.map(x=>`<button class="builder-ex ${selected.includes(x.id)?'chosen':''}" data-act="toggleCustomExercise" data-id="${x.id}"><img src="${x.image}" loading="lazy" alt=""><span class="grow"><b>${safe(x.name)}</b><small>${safe(x.dose)} · ${safe(x.muscles.join(', '))}</small></span><span class="selection-dot">${selected.includes(x.id)?'✓':'+'}</span></button>`).join('')}</div><button class="btn primary full" data-act="saveCustom">${ui.editingCustom?'Update':'Save'} custom workout (${selected.length} exercises)</button></div></div>`}
function customList(){return `<div class="section-title"><h2>Custom programme</h2><span>${customOptions().length} saved</span></div><div class="panel stack"><p class="tiny muted">Create a workout using any exercises from the library, then add it to your rotation or use it instead of one of A–D.</p><button class="btn primary full" data-act="newCustom">+ Build custom workout</button>${customOptions().map(w=>`<div class="flex-between custom-saved"><button class="link" data-act="open" data-id="${w.id}"><b>${safe(w.name)}</b> · ${w.exercises.length} exercises ${model.prefs.rotationAddons.some(a=>a.id===w.id)?'· In rotation':''}</button>${model.prefs.rotationAddons.some(a=>a.id===w.id)?`<button class="small-link" data-act="removeAddon" data-id="${w.id}">Unlink</button>`:''}<button class="small-link" data-act="editCustom" data-id="${w.id}">Edit</button><button class="small-link" data-act="deleteCustom" data-id="${w.id}">Delete</button></div>`).join('')}</div>`}
function customStartControls(w){if(!w.id.startsWith('custom-'))return '';return `<div class="panel stack"><h2>Where should this session go?</h2><p class="tiny muted">Choose a one-off extra workout, add it to the repeating sequence, or replace one A/B/C/D session this cycle. A full recovery day is still recommended after every completed session.</p><label class="choice-row"><input type="radio" name="custom-mode" value="extra" ${ui.customReplace==='extra'?'checked':''}> One-off extra (rotation unchanged)</label><label class="choice-row"><input type="radio" name="custom-mode" value="add" ${ui.customReplace==='add'?'checked':''}> Add to repeating rotation</label><label class="choice-row"><input type="radio" name="custom-mode" value="replace" ${ui.customReplace==='replace'?'checked':''}> Replace a rolling workout once</label><label>${ui.customReplace==='add'?'Insert after':'Replace'} which workout?<select id="custom-target" ${ui.customReplace==='extra'?'disabled':''}>${PROGRAMME.map(z=>`<option value="${z.id}" ${ui.customTarget===z.id?'selected':''}>${safe(z.name)} · ${safe(z.focus)}</option>`).join('')}</select></label></div>`}
function groups(){let all=library(),muscles=muscleGroups(all),types=[...new Set(all.map(equipment))].sort();let isM=ui.guideMode!=='type';let groups=isM?muscles:types;let selected=isM?ui.guideMuscle:ui.guideType;let chosen=selected==='all'?groups:groups.filter(g=>g===selected);return `<div class="kicker">EXPLORE BY CATEGORY</div><h1>Exercise groups</h1><p class="subtitle">Browse by target muscle or equipment and exercise type. Illustrations show the relevant movements.</p><div class="segmented"><button data-act="groupMode" data-mode="muscle" class="${isM?'on':''}">Muscle groups</button><button data-act="groupMode" data-mode="type" class="${!isM?'on':''}">Exercise types</button></div><div class="filter-row"><button class="filter ${selected==='all'?'selected':''}" data-act="groupPick" data-group="all">All</button>${groups.map(g=>`<button class="filter ${selected===g?'selected':''}" data-act="groupPick" data-group="${safe(g)}">${safe(g)}</button>`).join('')}</div><div class="group-list">${chosen.map(g=>{let xs=all.filter(x=>isM?matchesMuscle(x,g):equipment(x)===g);return `<section class="group-panel"><div class="group-title"><div class="muscle-illustration">${isM?muscleDiagram(g):icon('train')}</div><div><h2>${safe(g)}</h2><p class="tiny muted">${xs.length} exercises · ${isM?'Highlighted area is schematic':'Equipment classification'}</p></div></div><div class="group-exercises">${xs.map(x=>`<button class="group-exercise" data-act="detail" data-id="${x.id}"><img src="${x.image}" loading="lazy" alt="${safe(x.name)} anatomy"><span>${safe(x.name)}</span>${icon('arrow')}</button>`).join('')}</div></section>`}).join('')}</div>`}
function muscleDiagram(group){let g=group.toLowerCase(),red='var(--accent)',gray='#c6d2db';let hit=(...words)=>words.some(w=>g.includes(w)),c=(...w)=>hit(...w)?red:gray;
 const person=(back)=>`<g transform="translate(${back?76:0} 0)" stroke="#718296" stroke-width=".65"><circle cx="31" cy="15" r="10" fill="${gray}"/><path d="M17 27 Q31 23 45 27 L47 74 Q31 80 15 74Z" fill="${gray}"/><ellipse cx="11" cy="43" rx="7" ry="17" fill="${c(back?'rear shoulders':'deltoids','shoulders')}"/><ellipse cx="51" cy="43" rx="7" ry="17" fill="${c(back?'rear shoulders':'deltoids','shoulders')}"/><path d="M9 50l-3 21 8 1 3-21z" fill="${c('biceps','triceps','arms')}"/><path d="M53 50l3 21-8 1-3-21z" fill="${c('biceps','triceps','arms')}"/>${back?`<path d="M18 29Q31 40 44 29L44 53Q31 49 18 53Z" fill="${c('back','lats','upper back')}"/><ellipse cx="24" cy="75" rx="10" ry="10" fill="${c('glutes','hips')}"/><ellipse cx="39" cy="75" rx="10" ry="10" fill="${c('glutes','hips')}"/>`:`<ellipse cx="24" cy="36" rx="10" ry="9" fill="${c('chest')}"/><ellipse cx="38" cy="36" rx="10" ry="9" fill="${c('chest')}"/><rect x="23" y="48" width="16" height="20" rx="4" fill="${c('abs','core')}"/><path d="M16 68Q31 81 46 68L44 81H18z" fill="${c('hips')}"/>`}<path d="M18 81L16 112Q16 116 28 116L31 82Z" fill="${c(back?'hamstrings':'quads','legs','thighs')}"/><path d="M44 81L46 112Q46 116 34 116L31 82Z" fill="${c(back?'hamstrings':'quads','legs','thighs')}"/><rect x="18" y="112" width="11" height="24" rx="4" fill="${c('calves')}"/><rect x="34" y="112" width="11" height="24" rx="4" fill="${c('calves')}"/><path d="M18 135L13 141H29V135 M34 135v6H50l-5-6" fill="${gray}"/></g>`;
 return `<svg viewBox="0 0 140 162" role="img" aria-label="Schematic front and rear human muscle locations for ${safe(group)}">${person(false)}${person(true)}<text x="31" y="157" font-size="9" fill="currentColor" text-anchor="middle">Front</text><text x="107" y="157" font-size="9" fill="currentColor" text-anchor="middle">Back</text></svg>`;}

function monthCalendar(){let base=new Date(),first=new Date(base.getFullYear(),base.getMonth()+ui.monthOffset,1),month=first.getMonth(),year=first.getFullYear(),start=(first.getDay()+6)%7,total=new Date(year,month+1,0).getDate(),today=new Date();let byDay={};for(let s of model.sessions){let d=dateOf(s.date);if(d.getFullYear()!==year||d.getMonth()!==month)continue;(byDay[d.getDate()]||=[]).push(s)}let cells=Array.from({length:start+total},(_,i)=>i<start?null:i-start+1);while(cells.length%7)cells.push(null);return `<div class="kicker">YOUR TRAINING DIARY</div><h1>Monthly calendar</h1><p class="subtitle">Completed workouts are recorded here automatically. Tap a marked date to see the sessions you completed.</p><div class="panel stack"><div class="flex-between calendar-controls"><button class="btn secondary small" data-act="monthChange" data-step="-1">← Previous</button><h2>${first.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h2><button class="btn secondary small" data-act="monthChange" data-step="1">Next →</button></div><div class="calendar-grid">${['M','T','W','T','F','S','S'].map(x=>`<span class="day-label">${x}</span>`).join('')}${cells.map(day=>day?`<button class="calendar-day ${today.getDate()===day&&today.getMonth()===month&&today.getFullYear()===year?'today':''} ${byDay[day]?.length?'has-workout':''}" data-act="calendarDay" data-day="${day}"><b>${day}</b><span>${(byDay[day]||[]).map(s=>`<i title="${safe((s.workoutName||getWorkout(s.workout).name))}"></i>`).join('')}</span></button>`:'<span class="calendar-empty"></span>').join('')}</div><div class="calendar-details" id="calendar-details"><h3>Sessions this month</h3>${Object.keys(byDay).length?Object.entries(byDay).sort((a,b)=>Number(b[0])-Number(a[0])).map(([d,list])=>list.map(s=>`<button class="history-row" data-act="historyDetail" data-id="${safe(s.id)}"><span><b>${d} ${first.toLocaleDateString('en-GB',{month:'short'})} · ${safe((s.workoutName||getWorkout(s.workout).name))}</b><small>${totalSets(s)} sets completed</small></span>${icon('arrow')}</button>`).join('')).join(''):'<p class="tiny muted">No workouts recorded this month yet.</p>'}</div></div>`}
function lightbox() {
  const x = byId(ui.guideId);
  if (!x) return;
  const dialog = document.createElement('dialog');
  dialog.className = 'art-modal';
  dialog.setAttribute('aria-labelledby', 'art-title');
  dialog.innerHTML = `
    <div class="art-layout">
      <div class="art-header">
        <h2 id="art-title">${safe(x.name)}</h2>
        <button type="button" class="btn secondary small" data-act="closeArt" autofocus>Close ×</button>
      </div>
      <div class="art-frame">
        <img src="${safe(x.image)}" alt="Full exercise illustration of ${safe(x.name)}">
      </div>
      <p>${safe(x.note || 'Move slowly and use a comfortable range.')}</p>
    </div>`;
  dialog.addEventListener('close', () => dialog.remove(), { once: true });
  document.body.appendChild(dialog);
  dialog.showModal();
}
function audioUnlock(){if(!model.prefs.sound)return;try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume()}catch{}}
function beep(kind='tick'){if(!model.prefs.sound)return;try{audioUnlock();if(!audioCtx)return;let o=audioCtx.createOscillator(),g=audioCtx.createGain(),v=model.prefs.volume==='soft'?.035:model.prefs.volume==='loud'?.2:.095;let duration=kind==='finish'?.65:kind==='half'?.13:.11;o.type='sine';o.frequency.value=kind==='finish'?880:kind==='start'?760:kind==='half'?620:kind==='last'?900:520;g.gain.setValueAtTime(0.001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(v*(kind==='finish'?1.3:1),audioCtx.currentTime+.018);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration+.01)}catch{}}

function icon(name){let paths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 21v-7h6v7"/>',train:'<path d="M2 10v4m3-6v8m3-6v4m8-4v4m3-6v8m3-6v4M2 12h20"/>',guide:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h4"/>',progress:'<path d="m3 18 6-7 4 3 8-10"/><path d="M16 4h5v5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',ai:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M9 9l6 3-6 3z"/>',history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m4 12 5 5L20 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="m5 12 14 0m-6-6 6 6-6 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4M17.6 17.6 19 19M19 5l-1.4 1.4M6.4 17.6 5 19"/>',moon:'<path d="M20 15A8 8 0 0 1 9 4a8 8 0 1 0 11 11z"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 5 12 7-12 7z"/>',refresh:'<path d="M20 7A8 8 0 1 0 21 12M20 3v5h-5"/>'};return `<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.home}</svg>`}
function tabTo(page){ui.page=page;render();window.scrollTo(0,0)}
function workoutButton(w){let count=newSessions().filter(s=>s.workout===w.id).length;return `<button class="workout-tile" data-act="open" data-id="${w.id}"><span class="workout-symbol" style="background:${w.color}23;color:${w.color}">${w.emoji}</span><span class="grow"><b>${safe(w.name)}</b><small>${safe(w.focus)} · ${count} logged</small></span>${icon('arrow')}</button>`}
function home(){let info=nextInfo(),recent=sessionsSorted().slice(0,3),last28=model.sessions.filter(s=>now()-Number(s.date)<28*86400000),sets=last28.reduce((n,s)=>n+totalSets(s),0);return `<div class="kicker">YOUR TRAINING, YOUR RHYTHM</div><h1>Keep getting stronger<span class="dot">.</span></h1><p class="subtitle">Three gym sessions. One home session. As many recovery days as you need.</p>${model.draft?`<div class="notice"><b>Workout in progress</b><span>${safe(getWorkout(model.draft.workout).name)} · ${totalSets(model.draft)} sets completed</span><button class="btn" data-act="resume">Resume workout →</button></div>`:''}<section class="hero"><div class="flex-between"><span class="eyebrow">YOUR NEXT WORKOUT</span><span class="status ${info.ready?'ready':'recover'}">${info.ready?'Ready':'Rest day'}</span></div><h2>${safe(info.next.name)} <span>· ${safe(info.next.focus)}</span></h2><p>${info.last?`Last: ${safe(getWorkout(info.last.workout).name)} on ${dateShort(info.last.date)}.`:'Choose your first workout whenever you like.'} ${info.last?`Next eligible: ${dateLong(info.eligible)}.`:''}</p><div class="hero-actions"><button class="btn primary" data-act="open" data-id="${info.next.id}">View workout ${icon('arrow')}</button><button class="btn secondary" data-act="schedule">Change workout</button></div>${!info.ready?'<div class="hero-hint">Your recovery preference is advisory. You can still start a workout early.</div>':''}</section><div class="summary-grid"><div class="mini-stat"><span>Last 28 days</span><strong>${last28.length}</strong><small>sessions</small></div><div class="mini-stat"><span>Completed sets</span><strong>${sets}</strong><small>last 28 days</small></div><div class="mini-stat"><span>Next in rotation</span><strong>${info.next.id}</strong><small>flexible rolling schedule</small></div></div><div class="section-title"><h2>Your rolling programme</h2><span>Choose any session</span></div><div class="workout-list">${rotationList().map(workoutButton).join('')}</div>${customList()}<div class="section-title"><h2>Recent sessions</h2><button class="link" data-page="history">All history →</button></div>${recent.length?`<div class="panel">${recent.map(s=>`<button class="history-row" data-act="historyDetail" data-id="${safe(s.id)}"><span><b>${safe((s.workoutName||getWorkout(s.workout).name))}</b><small>${dateShort(s.date)} · ${totalSets(s)} sets</small></span>${icon('arrow')}</button>`).join('')}</div>`:'<div class="empty">Your training history starts when you finish your first workout.</div>'}`}
function schedule(){let info=nextInfo();return `<button class="back" data-page="home">← Home</button><div class="kicker">FLEXIBLE TRAINING</div><h1>Plan your next session</h1><p class="subtitle">No fixed weekdays or calendar-week resets.</p><div class="panel stack"><label class="field-label">Suggested workout</label><div class="pick-grid">${rotationList().map(w=>`<button class="pick ${info.next.id===w.id?'active':''}" data-act="manual" data-id="${w.id}"><b>${w.name}</b><small>${safe(w.focus)}</small></button>`).join('')}</div><button class="btn secondary full" data-act="automatic">Use automatic rotation instead</button><label class="field-label" for="restDays">Full rest days between sessions</label><select id="restDays" data-pref="restDays"><option value="1" ${model.prefs.restDays==1?'selected':''}>1 full day (default)</option><option value="2" ${model.prefs.restDays==2?'selected':''}>2 full days</option><option value="3" ${model.prefs.restDays==3?'selected':''}>3 full days</option></select><div class="info">${info.last?`After ${dateLong(info.last.date)}, the next recommended eligible day is <b>${dateLong(info.eligible)}</b>.`:'You can begin with any session today.'} You can always override this recommendation.</div></div><h2 class="minor-heading">Upcoming rotation</h2><div class="panel">${Array.from({length:rotationList().length},(_,i)=>i).map(i=>{let cycle=rotationList(),idx=(cycle.findIndex(w=>w.id===info.next.id)+i)%cycle.length,w=cycle[idx],d=info.last?plusCalendarDays(info.eligible,i*(Number(model.prefs.restDays)+1)):plusCalendarDays(now(),i*(Number(model.prefs.restDays)+1));return `<div class="schedule-row"><span class="schedule-num">${i+1}</span><span class="grow"><b>${w.name}</b><small>${w.focus}</small></span><span class="muted">${dateLong(d)}</span></div>`}).join('')}</div><p class="tip">These dates are suggestions only. Completing a workout, not merely selecting it, moves the rotation forward. If you train later, future suggestions shift automatically.</p>`}
function openWorkout(){let w=getWorkout(ui.openWorkout),rec=previousFor(w.exercises[0]?.id);return `<button class="back" data-page="home">← All workouts</button><div class="kicker">${w.place==='Home'?'AT-HOME TRAINING':'GYM TRAINING'}</div><h1>${w.name} <span class="muted">· ${w.focus}</span></h1><p class="subtitle">${w.id==='D'?'Guided mobility, functional strength, isometrics and stretching. Approximately 35–45 minutes.':'Strength work first. Use controlled technique and record your actual working sets.'}</p>${customStartControls(w)}<div class="panel flex-between"><div><b>${w.exercises.filter(x=>!x.optional).length} movements</b><p class="tiny muted">Repeat in the rolling A → B → C → D sequence</p></div><button class="btn primary" data-act="start" data-id="${w.id}">${model.draft?.workout===w.id?'Resume':'Start'} workout →</button></div><div class="section-title"><h2>Exercise guide</h2><span>Tap for coaching tips</span></div><div class="exercise-list">${w.exercises.filter(x=>!x.optional||model.prefs.includeOptional).map(x=>`<button class="exercise-row" data-act="detail" data-id="${x.id}"><img loading="lazy" class="art-contain" src="${x.image}" alt="${safe(x.name)} anatomical guide"><span class="grow"><b>${safe(x.name)}</b><small>${safe(x.dose)}${x.optional?' · Optional':''}</small></span>${icon('arrow')}</button>`).join('')}</div>`}
function setDefaults(x){return Array.from({length:x.sets||1},()=>({weight:'',reps:'',seconds:'',done:false}))}
function startWorkout(id,focus){if(model.draft&&model.draft.workout!==id){if(!confirm('You have another unfinished workout. Replace its draft? (Completed sessions remain safe.)'))return;}let w=getWorkout(id);if(model.draft?.workout!==id){let entries={};for(let x of w.exercises)entries[x.id]=setDefaults(x);model.draft={workout:id,started:now(),entries,notes:'',rounds:{},customMode:id.startsWith('custom-')?ui.customReplace:null,addonAfter:id.startsWith('custom-')?ui.customTarget:null,extra:id.startsWith('custom-')&&ui.customReplace==='extra',rotationSlot:id.startsWith('custom-')&&(ui.customReplace==='replace'?ui.customTarget:ui.customReplace==='add'?id:null)};save()}ui.openWorkout=id;tabTo('active');if(focus){setTimeout(()=>document.getElementById('ex-'+focus)?.scrollIntoView({behavior:'smooth',block:'start'}),50)}}
function copyPrevious(id){let prev=previousFor(id);if(!prev||!model.draft)return;let entry=model.draft.entries[id],from=prev.sets.filter(z=>z.done);entry.forEach((z,i)=>{let p=from[i]||from[from.length-1];if(p){z.weight=String(p.weight??'');z.reps=String(p.reps??'');z.seconds=String(p.seconds??'');z.done=false}});save();render();note('Previous set values copied. Check them before training.')}
function suggestion(x){if(x.unit!=='kg'||x.stage==='cardio'||x.stage==='warmup')return null;let last=previousFor(x.id);if(!last)return null;let sets=last.sets.filter(z=>z.done);if(sets.length<x.sets||!sets.every(z=>Number(z.reps)>=x.hi&&Number(z.weight)>0))return null;let weights=sets.map(z=>Number(z.weight)),min=Math.min(...weights),max=Math.max(...weights);if(min!==max)return null;let increment=['squat','rdl','legpress','thrust','reverse','calfstand'].includes(x.id)?5:2.5;return `You reached ${x.hi} reps in all ${x.sets} sets last time. Consider ${min+increment} kg next time if technique and effort were good.`}
function setMarkup(x,i,z){let previous=previousFor(x.id)?.sets?.[i];let isTime=x.unit==='sec'||x.kind==='isometric'||x.kind==='stretch';let hasWeight=x.unit==='kg'&&x.stage!=='cardio';let valueField=x.unit==='min'?'minutes':isTime?'seconds':'reps';let v=isTime?z.seconds:z.reps;const entry=(key,label,value)=>`<button type="button" class="entry-box entry-button" data-act="numberEntry" data-id="${x.id}" data-i="${i}" data-field="${key}" aria-label="Enter ${label.toLowerCase()} for ${safe(x.name)} set ${i+1}"><span>${label}</span><strong>${safe(value)||'<em>Tap to enter</em>'}</strong></button>`;return `<div class="set-row ${z.done?'completed':''}"><span class="set-number">${i+1}</span>${hasWeight?entry('weight','KG',z.weight):''}${entry(isTime?'seconds':'reps',valueField.toUpperCase(),v)}<button class="set-check ${z.done?'checked':''}" data-act="tick" data-id="${x.id}" data-i="${i}" aria-label="${z.done?'Undo':'Complete'} set ${i+1}">${icon('check')}</button>${isTime?`<button class="timer-mini" data-act="holdStart" data-id="${x.id}" data-i="${i}" aria-label="Start ${x.name} timer">${icon('clock')}</button>`:''}${previous?`<small class="set-prev">Last: ${safe(previous.weight||'')}${previous.weight?' kg · ':''}${safe(previous.seconds||previous.reps||'')}${previous.seconds?'s':''}</small>`:''}</div>`}
function stageGroup(w,stage){let list=w.exercises.filter(x=>x.stage===stage&&(!x.optional||model.prefs.includeOptional));if(!list.length)return '';let sets=list.reduce((m,x)=>Math.max(m,x.sets),1),done=model.draft.rounds[stage]||0;return `<section class="stage"><div class="stage-heading"><div><span class="eyebrow">HOME D · ${stage.toUpperCase()}</span><h2>${stage==='Mobility'?'Joint mobility':stage==='Circuit'?'Functional circuit':stage==='Isometrics'?'Isometric holds':stage==='Cool-down'?'Cool-down stretches':'Extra movements'}</h2><small>${stage==='Circuit'||stage==='Isometrics'?`${sets} rounds · Rest as needed`:'Controlled movement · Stay within a comfortable range'}</small></div>${(stage==='Circuit'||stage==='Isometrics')?`<span class="round-pill">Round ${Math.min(done+1,sets)} / ${sets}</span>`:''}</div>${list.map(x=>exerciseLive(x)).join('')}${(stage==='Circuit'||stage==='Isometrics')?`<button class="btn secondary full" data-act="round" data-id="${stage}">${done>=sets?'Rounds completed ✓':`Mark round ${done+1} complete`}</button>`:''}</section>`}
function exerciseLive(x){let arr=model.draft.entries[x.id];let last=previousFor(x.id);let sugg=suggestion(x);let completedCount=arr.filter(z=>z.done).length;return `<section class="exercise-live" id="ex-${x.id}"><div class="exercise-top"><button class="exercise-illustration" data-act="detail" data-id="${x.id}"><img loading="lazy" class="art-contain" src="${x.image}" alt="Exercise technique illustration for ${safe(x.name)}"></button><div class="grow"><span class="exercise-tag">${x.kind==='isometric'?'ISOMETRIC':x.stage?.toUpperCase()||'STRENGTH'}</span><h3>${safe(x.name)}</h3><p>${safe(x.dose)} · ${completedCount}/${x.sets} completed</p><button class="text-btn" data-act="detail" data-id="${x.id}">Technique guide ↗</button></div></div>${x.note?`<p class="exercise-note">${safe(x.note)}</p>`:''}${last?`<div class="last-wrap"><span>Last: ${dateShort(last.s.date)}</span><button class="small-link" data-act="copy" data-id="${x.id}">Copy last values</button></div>`:''}${sugg?`<div class="suggestion">${icon('progress')} ${safe(sugg)}</div>`:''}<div class="set-head"><span>SET</span>${x.unit==='kg'&&x.stage!=='cardio'?'<span>WEIGHT</span>':''}<span>${x.unit==='sec'||x.kind==='isometric'||x.kind==='stretch'?'HOLD':x.unit==='min'?'MINUTES':'REPS'}</span><span>DONE</span></div>${arr.map((z,i)=>setMarkup(x,i,z)).join('')}</section>`}
function active(){if(!model.draft)return home();let w=getWorkout(model.draft.workout),done=totalSets(model.draft),all=Object.values(model.draft.entries).reduce((n,arr)=>n+arr.length,0);return `<div class="sticky-workout"><div><span class="kicker">ACTIVE WORKOUT</span><h2>${w.name} · ${w.focus}</h2><small>${done} of ${all} sets completed · Entries save as you type</small></div><button class="btn secondary small" data-act="pauseWorkout">Exit</button></div>${w.id==='D'?`<div class="info">Follow each stage in order. Timers record your actual hold duration. The optional moves can be enabled in Settings.</div>${['Mobility','Circuit','Isometrics','Cool-down','Optional'].map(stage=>stageGroup(w,stage)).join('')}${scanExerciseList(model.draft).filter(x=>!w.exercises.some(y=>y.id===x.id)).map(x=>exerciseLive(x)).join('')}`:scanExerciseList(model.draft).map(x=>exerciseLive(x)).join('')}<div class="panel stack"><label class="field-label" for="session-notes">Session notes (optional)</label><textarea id="session-notes" rows="2" placeholder="How did the workout feel?">${safe(model.draft.notes||'')}</textarea><div class="action-row"><button class="btn secondary" data-act="discard">Discard draft</button><button class="btn primary" data-act="finish">Finish & save workout</button></div></div>`}
function finish(){if(!model.draft)return;let count=totalSets(model.draft);if(count===0){note('Complete at least one set before saving.');return}if(!confirm(`Save ${getWorkout(model.draft.workout).name} with ${count} completed sets?`))return;let s={...model.draft,id:'v2-'+now()+'-'+Math.random().toString(36).slice(2,7),date:now(),legacy:false,workoutName:getWorkout(model.draft.workout).name,exerciseSnapshots:scanExerciseList(model.draft).map(x=>({id:x.id,name:x.name,muscles:x.muscles}))};model.sessions.push(s);if(s.customMode==='add'&&!model.prefs.rotationAddons.some(a=>a.id===s.workout)){model.prefs.rotationAddons.push({id:s.workout,after:s.addonAfter||'D'})}model.draft=null;model.prefs.manualNext=null;save();restStop();holdStop(false);tabTo('history');note('Workout saved. Your next session has updated.');}
function guide(){let exercises=PROGRAMME.filter(w=>ui.guideFilter==='all'||w.id===ui.guideFilter).flatMap(w=>w.exercises.filter(x=>!x.optional||model.prefs.includeOptional)).filter(x=>(x.name+' '+x.muscles.join(' ')).toLowerCase().includes((ui.guideSearch||'').toLowerCase()));return `<div class="kicker">ILLUSTRATED TECHNIQUE</div><h1>Exercise guide</h1><button class="btn primary" data-page="ai">Scan a gym machine with AI →</button> <button class="btn secondary" data-page="groups">Explore exercise groups →</button><p class="subtitle">Tap an anatomical illustration for targets, form cues and tracking history.</p><section class="panel machine-guides"><h2>Machine demos</h2><div class="machine-guide-list">${machineGuides.map(machine=>`<button type="button" class="btn secondary small" data-act="detail" data-id="${machine.exerciseId}">${safe(machine.name)}</button>`).join('')}</div></section><div class="filter-row"><button type="button" class="filter ${ui.guideFilter==='all'?'selected':''}" data-filter="all">All</button>${PROGRAMME.map(w=>`<button type="button" class="filter ${ui.guideFilter===w.id?'selected':''}" data-filter="${w.id}">${w.name}</button>`).join('')}</div><div class="search-wrap"><input type="search" autocapitalize="off" autocomplete="off" spellcheck="false" class="search" id="guide-search" placeholder="Search movements or muscles…" aria-label="Search exercises" value="${safe(ui.guideSearch)}"><div class="search-actions"><button type="button" class="btn secondary small" data-act="guidePrompt">Type</button><button type="button" class="btn secondary small" data-act="guideSearch">Search</button><button type="button" class="btn secondary small" data-act="guideClear">Clear</button></div></div><p class="tiny muted">${exercises.length} exercise${exercises.length===1?'':'s'} shown</p><div class="exercise-list">${exercises.map(x=>`<button class="exercise-row" data-act="detail" data-id="${x.id}"><img loading="lazy" class="art-contain" src="${x.image}" alt="${safe(x.name)} guide"><span class="grow"><b>${safe(x.name)}</b><small>${safe(x.dose)} · ${safe(x.muscles.join(', '))}</small></span>${icon('arrow')}</button>`).join('')}</div>`}
function detail(){let x=byId(ui.guideId),w=PROGRAMME.find(w=>w.exercises.some(z=>z.id===x?.id));if(!x)return guide();let last=previousFor(x.id);const machine=machineGuides.find(item=>item.exerciseId===x.id);return `<button class="back" data-act="detailBack">← Back</button><div class="kicker">ANATOMICAL GUIDE</div><h1>${safe(x.name)}</h1><p class="subtitle">${safe(x.dose)}</p>${machine?`<exercise-motion class="panel" data-machine="${machine.id}"></exercise-motion>`:''}<div class="panel"><button class="detail-zoom" data-act="showArt" data-id="${x.id}" aria-label="Enlarge ${safe(x.name)} anatomical illustration"><img class="detail-art" src="${x.image}" alt="Full anatomical illustration of ${safe(x.name)}"><span>Tap to enlarge illustration ⤢</span></button><div class="tag-row">${x.muscles.map(m=>`<span class="muscle-tag">${safe(m)}</span>`).join('')}</div><h3>Technique cues</h3><p class="note-text">${safe(x.note||'Move through a controlled, comfortable range of motion.')}</p><p class="tiny muted">Illustrations are visual references, not a substitute for coaching. Stop if an exercise causes pain.</p>${last?`<p class="tiny">Last logged: ${dateShort(last.s.date)} · ${last.sets.filter(z=>z.done).length} sets</p>`:''}${w?`<button class="btn primary full" data-act="startEx" data-id="${w.id}" data-focus="${x.id}">Log this exercise →</button>`:''}</div>`}
function history(){let list=sessionsSorted();return `<div class="kicker">YOUR RECORD</div><h1>Training history</h1><p class="subtitle">Your original four-gym-day sessions remain archived alongside the new programme.</p><div class="panel">${list.length?list.map(s=>`<button class="history-row" data-act="historyDetail" data-id="${safe(s.id)}"><span><b>${safe((s.workoutName||getWorkout(s.workout).name))} ${s.legacy?'<span class="archive-tag">Original programme</span>':''}</b><small>${dateShort(s.date)} · ${totalSets(s)} completed sets</small></span>${icon('arrow')}</button>`).join(''):'<div class="empty">No completed workouts yet.</div>'}</div>`}
function historyDetail(){let s=model.sessions.find(x=>x.id===ui.historyId);if(!s)return history();return `<button class="back" data-page="history">← History</button><div class="kicker">COMPLETED SESSION</div><h1>${safe((s.workoutName||getWorkout(s.workout).name))}</h1><p class="subtitle">${dateLong(s.date)} · ${totalSets(s)} sets ${s.legacy?'· Original programme':''}</p><div class="panel">${Object.entries(s.entries||{}).map(([id,arr])=>{let z=arr.filter(x=>x.done);if(!z.length)return '';return `<div class="history-ex"><b>${safe(exerciseLabel(id))}</b>${z.map((x,i)=>`<small>Set ${i+1}: ${x.weight?`${safe(x.weight)} kg · `:''}${safe(x.seconds||x.reps||'–')} ${x.seconds?'sec':'reps'}</small>`).join('')}</div>`}).join('')}${s.notes?`<p class="note-text">${safe(s.notes)}</p>`:''}</div><button class="btn danger" data-act="deleteHistory" data-id="${safe(s.id)}">Delete this workout</button>`}
function svgGraph(vals){if(!vals.length)return '<div class="empty">No completed weighted sets yet.</div>';let points=vals.slice(-18),min=Math.min(...points.map(v=>v.weight)),max=Math.max(...points.map(v=>v.weight));let range=Math.max(1,max-min);const coords=points.map((p,i)=>[16+i* (310/Math.max(1,points.length-1)),115-(p.weight-min)/range*85]);return `<svg viewBox="0 0 345 145" class="chart-svg" role="img" aria-label="Weight progression line graph"><path d="M16 115H329M16 72H329M16 29H329" stroke="currentColor" opacity=".12" fill="none"/><polyline fill="none" stroke="var(--accent)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="${coords.map(p=>p.join(',')).join(' ')}"/>${coords.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3.7" fill="var(--accent)"/>`).join('')}<text x="16" y="139" font-size="10" fill="currentColor">${dateShort(points[0].date)}</text><text x="329" y="139" font-size="10" text-anchor="end" fill="currentColor">${dateShort(points[points.length-1].date)}</text></svg>`}
function progress(){let days=ui.statPeriod,cut=now()-days*86400000,filtered=model.sessions.filter(s=>s.date>=cut),volume={},best={},holds={};for(let session of model.sessions)for(let [id,arr] of Object.entries(session.entries||{})){let x=byId(id);if(!x)continue;for(let z of arr.filter(z=>z.done)){let kg=Number(z.weight);if(kg>0&&(!best[id]||kg>best[id].weight))best[id]={weight:kg,reps:Number(z.reps)||0,date:session.date};if(Number(z.seconds)>0)holds[id]=Math.max(holds[id]||0,Number(z.seconds));if(session.date>=cut&&x.unit!=='min'&&!['warmup','cardio'].includes(x.stage)&&!['stretch','mobility'].includes(x.kind))x.muscles.forEach((m,i)=>volume[m]=(volume[m]||0)+(i?0.5:1));}}let options=library().filter(x=>x.unit==='kg'),exercise=byId(ui.progressId)||options[0],values=completedLoads(exercise?.id),pr=Object.entries(best).sort((a,b)=>b[1].date-a[1].date).slice(0,15),tab=ui.progressTab||'strength';return `<div class="kicker">MEANINGFUL PROGRESS</div><h1>Your progress</h1><p class="subtitle">Track training, mobility and personal bests. Every view below is interactive.</p><div class="summary-grid"><div class="mini-stat"><span>Workouts</span><strong>${filtered.length}</strong><small>last ${days} days</small></div><div class="mini-stat"><span>Personal bests</span><strong>${Object.keys(best).length}</strong><small>weighted exercises</small></div><div class="mini-stat"><span>Hold records</span><strong>${Object.keys(holds).length}</strong><small>timed movements</small></div></div><div id="progress-controls" class="progress-view-grid" role="group" aria-label="Choose progress view">${[['strength','Strength'],['muscles','Muscles'],['records','Records'],['mobility','Mobility']].map(([id,label])=>`<button type="button" data-act="progressTab" data-tab="${id}" aria-pressed="${tab===id}" class="progress-view-button ${tab===id?'on':''}">${label}</button>`).join('')}</div>${tab==='strength'?`<div class="panel stack"><h2>Strength trends</h2><div id="strength-exercise-picker" class="progress-exercise-picker"><span class="field-label">Select exercise</span><button type="button" class="exercise-picker-trigger" data-act="toggleExercisePicker" aria-expanded="${!!ui.progressPickerOpen}"><span>${safe(exercise?.name||'Choose exercise')}</span><span aria-hidden="true">${ui.progressPickerOpen?'▲':'▼'}</span></button>${ui.progressPickerOpen?`<div class="progress-exercise-list" role="group" aria-label="Strength exercise options">${options.map(x=>`<button type="button" data-act="progressExercise" data-id="${x.id}" aria-pressed="${exercise?.id===x.id}" class="exercise-picker-item ${exercise?.id===x.id?'chosen':''}">${safe(x.name)}${exercise?.id===x.id?' ✓':''}</button>`).join('')}</div>`:''}</div>${svgGraph(values)}${values.length?`<div class="insight">Best recorded load: <b>${Math.max(...values.map(v=>v.weight))} kg</b>. Consider reps, form and effort alongside weight.</div>`:''}</div>`:''}${tab==='muscles'?`<div class="panel stack"><div class="flex-between"><h2>Muscle-group training</h2><div class="period-buttons" role="group" aria-label="Training period">${[7,28,84].map(n=>`<button type="button" class="period-button ${n===days?'on':''}" data-act="progressPeriod" data-days="${n}" aria-pressed="${n===days}">${n}d</button>`).join('')}</div></div><p class="tiny muted">Completed set exposure; secondary muscles count 0.5. This does not directly measure muscle growth.</p>${Object.keys(volume).length?Object.entries(volume).sort((a,b)=>b[1]-a[1]).map(([m,v])=>`<div class="muscle-meter"><div class="flex-between"><span>${safe(m)}</span><b>${v.toFixed(v%1?1:0)} sets</b></div><div class="meter"><i style="width:${Math.min(100,v/Math.max(1,...Object.values(volume))*100)}%"></i></div></div>`).join(''):'<div class="empty">Complete strength workouts to see muscle-group volume.</div>'}</div>`:''}${tab==='records'?`<div class="panel stack"><h2>Personal records</h2>${pr.length?pr.map(([id,p])=>`<div class="stat-row"><span>${safe(exerciseLabel(id))}</span><b>${p.weight} kg</b></div>`).join(''):'<div class="empty">Record completed sets to see personal bests.</div>'}<h3>Timed holds</h3>${Object.keys(holds).length?Object.entries(holds).sort((a,b)=>b[1]-a[1]).map(([id,v])=>`<div class="stat-row"><span>${safe(exerciseLabel(id))}</span><b>${v} sec</b></div>`).join(''):'<p class="tiny muted">Your isometric records will appear here.</p>'}</div>`:''}${tab==='mobility'?`<div class="panel stack"><h2>Mobility assessments</h2><p class="tiny muted">Use the same test position each time. Record your comfortable range without forcing movement.</p><div class="mobility-grid"><label>Knee-to-wall left (cm)<input type="text" inputmode="decimal" id="ankle-left" placeholder="e.g. 8.5"></label><label>Knee-to-wall right (cm)<input type="text" inputmode="decimal" id="ankle-right" placeholder="e.g. 9"></label><label>90/90 hip control (1–5)<select id="hip-quality">${[1,2,3,4,5].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label><label>Overhead reach (1–5)<select id="shoulder-quality">${[1,2,3,4,5].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label></div><button class="btn primary full" data-act="saveAssessment">Save mobility assessment</button>${model.assessments.length?`<h3>Previous assessments</h3>${model.assessments.slice().reverse().map(a=>`<div class="history-row"><span><b>${dateShort(a.date)}</b><small>Ankle L ${a.left} cm · R ${a.right} cm · Hips ${a.hip}/5 · Shoulders ${a.shoulder}/5</small></span></div>`).join('')}`:'<p class="tiny muted">No assessments recorded yet.</p>'}</div>`:''}`;}
function settings(){return `<div class="kicker">MAKE IT YOURS</div><h1>Settings</h1><p class="subtitle">A personal, offline-first tracker. All workout history is saved on this device.</p><div class="panel stack"><h2>Appearance</h2><div class="pick-grid three">${['light','dark','system'].map(t=>`<button class="pick ${model.prefs.theme===t?'active':''}" data-theme="${t}"><b>${t==='system'?'Auto':t[0].toUpperCase()+t.slice(1)}</b><small>${t==='system'?'Phone setting':t==='dark'?'Dark palette':'Light palette'}</small></button>`).join('')}</div><h3>Background colour theme</h3><p class="tiny muted">Choose independently of Light / Dark / System.</p><div class="palette-list">${[['ocean','#2b887f'],['plum','#9368b1'],['sand','#c58d54'],['forest','#408d64'],['slate','#62799c']].map(([name,hex])=>`<button data-color="${name}" class="palette ${model.prefs.color===name?'selected':''}" style="--swatch:${hex}"><span></span>${name}</button>`).join('')}</div></div><div class="panel stack"><h2>Training preferences</h2><label class="field-label" for="rest-select">Full rest days between workouts</label><select id="rest-select" data-pref="restDays">${[1,2,3].map(n=>`<option value="${n}" ${model.prefs.restDays==n?'selected':''}>${n} day${n>1?'s':''}</option>`).join('')}</select><label class="field-label" for="rest-timer">Rest timer after each gym set</label><select id="rest-timer" data-pref="restSeconds">${[0,60,90,120,180].map(n=>`<option value="${n}" ${model.prefs.restSeconds==n?'selected':''}>${n?n+' seconds':'Off'}</option>`).join('')}</select><label class="field-label">Preparation countdown</label><select data-pref="prepSeconds">${[0,3,5,10].map(n=>`<option value="${n}" ${model.prefs.prepSeconds==n?'selected':''}>${n?n+' seconds':'Off'}</option>`).join('')}</select><label class="field-label">Timer sound level</label><select id="volume-select">${['soft','normal','loud'].map(n=>`<option value="${n}" ${model.prefs.volume===n?'selected':''}>${n}</option>`).join('')}</select><label class="toggle-row"><input type="checkbox" id="sound-enabled" ${model.prefs.sound?'checked':''}> Sound alerts</label><button class="btn secondary small" data-act="testSound">Test alert sound</button><label class="toggle-row"><input type="checkbox" id="show-optional" ${model.prefs.includeOptional?'checked':''}> Show optional Home D progressions</label></div><div class="panel stack"><h2>Backup and restore</h2><p class="tiny muted">Your workout data is private to this device and website storage. Before removing the Home Screen app or changing devices, download a backup. A Netlify update at the same address should not erase records, but a backup is essential.</p><button class="btn primary full" data-act="backup">Download JSON backup</button><button class="btn secondary full" data-act="csv">Export all workouts to CSV</button><label class="file-label">Restore a saved backup <input type="file" id="import-file" accept=".json,application/json"></label><p class="tiny muted">Restoring replaces the current v2 record after confirmation. Original v1 storage is retained separately on this device.</p></div><div class="panel stack"><h2>Storage and updates</h2><div class="stat-row"><span>Completed workouts</span><b>${model.sessions.length}</b></div><div class="stat-row"><span>Original sessions preserved</span><b>${model.sessions.filter(s=>s.legacy).length}</b></div><div class="stat-row"><span>Storage</span><b>${db?'IndexedDB + backup':'Local fallback'}</b></div><button class="btn secondary full" data-act="checkUpdate">Check for app updates</button><p class="tiny muted">Version 3.3.5 · Includes your cropped Home D illustrations and touch-friendly Progress controls.</p></div>`}
function page(){return ui.page==='ai'?window.MyStrengthAI?.page?.()||'<div class="panel">Loading AI machine guide…</div>':ui.page==='home'?home():ui.page==='schedule'?schedule():ui.page==='workout'?openWorkout():ui.page==='active'?active():ui.page==='guide'?guide():ui.page==='detail'?detail():ui.page==='progress'?progress():ui.page==='groups'?groups():ui.page==='custom'?customBuilder():ui.page==='calendar'?monthCalendar():ui.page==='history'?history():ui.page==='historyDetail'?historyDetail():settings()}
function header(){return `<header class="topbar"><button class="brand" data-page="home"><span class="brand-icon">${icon('train')}</span><span><b>my strength<span class="dot">.</span></b><small>TRAIN WITH INTENTION</small></span></button><div class="top-actions"><button class="icon-btn" data-act="themeToggle" aria-label="Toggle light and dark mode">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><span class="v-tag">v${VERSION}</span></div></header>`}
const tabs=[['home','Home'],['train','Train'],['guide','Guide'],['ai','AI Scan'],['calendar','Calendar'],['progress','Progress'],['settings','Settings']];
function nav(){return `<nav class="bottom-nav" aria-label="Main navigation">${tabs.map(([id,label])=>`<button class="${ui.page===id||(id==='train'&&['workout','active','schedule'].includes(ui.page))?'selected':''}" data-page="${id}">${icon(id==='train'?'train':id)}<span>${label}</span></button>`).join('')}</nav>`}
function train(){return `<div class="kicker">YOUR TRAINING PLAN</div><h1>Choose a workout</h1><p class="subtitle">Follow the suggested rotation or train any day that suits you.</p><div class="workout-list">${rotationList().map(workoutButton).join('')}</div>${customList()}<button class="btn secondary full" data-act="schedule">Adjust next workout & recovery →</button>${model.draft?`<button class="btn primary full" data-act="resume">Resume unfinished workout →</button>`:''}`}

function renderProgressAt(anchor){render();requestAnimationFrame(()=>{const node=document.getElementById(anchor||'progress-controls');if(node)node.scrollIntoView({block:'start',behavior:'instant'});});}
function bindUI(){
  const gs=document.getElementById('guide-search');
  if(gs){gs.addEventListener('focus',()=>{ui.guideSearch=gs.value||ui.guideSearch||''});}
  const bs=document.getElementById('builder-search');
  if(bs){bs.addEventListener('focus',()=>{ui.guideSearch=bs.value||ui.guideSearch||''});}

}
function render(){if(!$('#app'))return;themeApply();$('#app').innerHTML=`${header()}<main class="container">${ui.page==='train'?train():page()}</main>${nav()}<div class="toast-holder"></div><div id="timer-dock" class="timer-dock" style="display:none"></div>`;updateTimerDock();if(ui.page==='ai')window.MyStrengthAI?.mounted?.()}
function restStop(){rest={end:0,remaining:0,running:false,label:''};updateTimerDock()}
function restStart(){const s=Number(model.prefs.restSeconds);if(!s)return;audioUnlock();timerLast.rest=null;rest={end:now()+s*1000,remaining:s,running:true,label:'Rest between sets'};updateTimerDock()}
function holdStop(record){if(record&&hold.id&&!hold.prep&&model.draft){let z=model.draft.entries?.[hold.id]?.[hold.index];if(z){let elapsed=Math.max(1,Math.round((hold.started?now()-hold.started:0)/1000));let target=Number(byId(hold.id)?.lo)||30;z.seconds=String(Math.min(Math.max(elapsed,target-hold.remaining),3600));save();refreshEntry(hold.id,hold.index)}}hold={end:0,remaining:0,running:false,id:null,index:0,started:0};updateTimerDock()}
function holdStart(id,index){let x=byId(id),z=model.draft?.entries?.[id]?.[index];if(!x||!z)return;holdStop(false);audioUnlock();let total=Number(z.seconds)||Number(x.lo)||30,prep=Number(model.prefs.prepSeconds)||0;hold={end:now()+prep*1000,remaining:prep||total,running:true,id,index,started:prep?0:now(),prep,total};timerLast.hold=null;if(!prep)beep('start');updateTimerDock()}
function fmtTime(v){let n=Math.max(0,Math.ceil(v));return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}
function updateTimerDock(){const box=$('#timer-dock');if(!box)return;if(hold.id){box.style.display='flex';box.innerHTML=`<span class="grow"><b>${safe(byId(hold.id)?.name||'Hold timer')}</b><small>${hold.prep?'GET READY · Starting soon':hold.running?'Hold countdown running':'Paused'}</small></span><strong>${hold.prep?'READY '+hold.remaining:fmtTime(hold.remaining)}</strong><button data-act="holdPause">${icon(hold.running?'pause':'play')}</button><button data-act="holdDone" class="timer-finish">Done</button>`;return}if(rest.remaining>0){box.style.display='flex';box.innerHTML=`<span class="grow"><b>Rest timer</b><small>${rest.running?'Next set soon':'Paused'}</small></span><strong>${fmtTime(rest.remaining)}</strong><button data-act="restPause">${icon(rest.running?'pause':'play')}</button><button data-act="restSkip">Skip</button>`;return}box.style.display='none'}
function tick(id,i){const z=model.draft?.entries?.[id]?.[i];if(!z)return;z.done=!z.done;if(z.done&&byId(id)?.unit==='kg')restStart();save();let parent=document.getElementById('ex-'+id);if(parent){let row=parent.querySelectorAll('.set-row')[i];row?.classList.toggle('completed',z.done);let b=row?.querySelector('.set-check');b?.classList.toggle('checked',z.done);if(b)b.setAttribute('aria-label',(z.done?'Undo':'Complete')+' set '+(i+1));let count=parent.querySelector('.exercise-top p');if(count)count.textContent=`${byId(id).dose} · ${model.draft.entries[id].filter(x=>x.done).length}/${byId(id).sets} completed`}else render()}
function refreshEntry(id,i){let x=document.getElementById('ex-'+id),z=model.draft?.entries?.[id]?.[i];if(!x||!z)return;let row=x.querySelectorAll('.set-row')[i];for(let btn of row?.querySelectorAll('[data-field]')||[]){let k=btn.dataset.field;let strong=btn.querySelector('strong');if(strong)strong.innerHTML=z[k]?safe(z[k]):'<em>Tap to enter</em>'}}
function editEntry(el){if(!model.draft)return;let x=byId(el.dataset.ex),z=model.draft.entries[el.dataset.ex]?.[Number(el.dataset.i)];if(!z)return;let field=el.dataset.entry,raw=el.value.replace(',', '.');if(field==='reps'||field==='seconds')raw=raw.replace(/[^\d]/g,'').slice(0,5);else {raw=raw.replace(/[^\d.]/g,'');let parts=raw.split('.');raw=parts[0].slice(0,5)+(parts.length>1?'.'+parts.slice(1).join('').slice(0,2):'')}z[field]=raw;if(el.value!==raw)el.value=raw;save()}
function numberEntryOpen(id,i,field){const z=model.draft?.entries?.[id]?.[i];if(!z)return;entryModal={id,i,field,value:String(z[field]??'')};numberEntryRender();}
function numberEntryRender(){if(!entryModal)return;document.getElementById('number-entry-overlay')?.remove();const e=entryModal,ex=byId(e.id),label=e.field==='weight'?'Weight (kg)':e.field==='seconds'?'Duration (seconds)':'Repetitions';let wrap=document.createElement('div');wrap.id='number-entry-overlay';wrap.className='number-overlay';wrap.innerHTML=`<div class="number-modal" role="dialog" aria-modal="true" aria-label="Enter ${label}"><div class="flex-between"><div><p class="kicker">SET ${e.i+1} · ${safe(ex?.name||'')}</p><h2>${label}</h2></div><button class="number-close" type="button" data-act="numberCancel" aria-label="Close keypad">×</button></div><div class="number-display" id="number-display" role="status" aria-live="polite">${safe(e.value)||'0'}</div><p class="number-help">Tap the large digits to enter your number. No second iPhone keyboard.</p><div class="number-grid">${['1','2','3','4','5','6','7','8','9',e.field==='weight'?'.':'Clear','0','⌫'].map(k=>`<button type="button" data-act="numberKey" data-key="${safe(k)}" ${k==='⌫'?'aria-label="Backspace"':''}>${k}</button>`).join('')}</div><div class="number-actions"><button class="btn secondary" type="button" data-act="numberClear">Clear</button><button class="btn primary" type="button" data-act="numberDone">Save & close</button></div></div>`;document.body.appendChild(wrap);document.body.classList.add('number-open');}
function cleanNumber(raw,field){raw=String(raw??'').replace(',','.');if(field!=='weight')return raw.replace(/[^0-9]/g,'').slice(0,5);let match=raw.replace(/[^0-9.]/g,'').split('.');return match[0].slice(0,5)+(match.length>1?'.'+match.slice(1).join('').slice(0,2):'')}
function numberKey(k){if(!entryModal)return;let e=entryModal,value=e.value;if(k==='Clear')value='';else if(k==='⌫')value=value.slice(0,-1);else if(k==='.'&&value.includes('.'))return;else value+=k;e.value=cleanNumber(value,e.field);const d=document.getElementById('number-display');if(d)d.textContent=e.value||'0'}
function numberEntryCommit(close){if(!entryModal)return;let e=entryModal,z=model.draft?.entries?.[e.id]?.[e.i];if(z){z[e.field]=cleanNumber(e.value,e.field);save();refreshEntry(e.id,e.i)}if(close){entryModal=null;document.getElementById('number-entry-overlay')?.remove();document.body.classList.remove('number-open')}}
function doClick(el){if(el.dataset.page){tabTo(el.dataset.page);return}let a=el.dataset.act,id=el.dataset.id;if(['saveCustom','toggleCustomExercise','customClear','deleteCustom','editCustom','newCustom','removeAddon','groupMode','groupPick','monthChange','calendarDay','progressTab','showArt','closeArt','numberClear','testSound','checkUpdate','guideSearch','guideClear','builderSearch','builderClear','guidePrompt','builderPrompt','toggleExercisePicker','progressExercise','progressPeriod'].includes(a)){extraClick(el);return}if(a==='themeToggle'){model.prefs.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';save();render()}else if(a==='open'){ui.openWorkout=id;if(id.startsWith('custom-')){let addon=model.prefs.rotationAddons.find(a=>a.id===id);ui.customReplace=addon?'add':'extra';ui.customTarget=addon?.after||(nextInfo().next.id.startsWith('custom-')?'A':nextInfo().next.id)}tabTo('workout')}else if(a==='start')startWorkout(id);else if(a==='startEx')startWorkout(id,el.dataset.focus);else if(a==='resume'){if(model.draft)tabTo('active')}else if(a==='schedule')tabTo('schedule');else if(a==='manual'){model.prefs.manualNext=id;save();render();note(getWorkout(id).name+' selected as next workout')}else if(a==='automatic'){model.prefs.manualNext=null;save();render()}else if(a==='detail'){ui.from=ui.page;ui.guideId=id;tabTo('detail')}else if(a==='detailBack')tabTo(ui.from==='active'?'active':ui.from==='workout'?'workout':ui.from==='groups'?'groups':'guide');else if(a==='numberEntry')numberEntryOpen(id,Number(el.dataset.i),el.dataset.field);else if(a==='numberKey')numberKey(el.dataset.key);else if(a==='numberDone')numberEntryCommit(true);else if(a==='numberCancel')numberEntryCommit(true);else if(a==='tick')tick(id,Number(el.dataset.i));else if(a==='copy')copyPrevious(id);else if(a==='holdStart')holdStart(id,Number(el.dataset.i));else if(a==='holdPause'){if(hold.running){hold.remaining=Math.max(0,Math.ceil((hold.end-now())/1000));hold.running=false}else{hold.end=now()+hold.remaining*1000;hold.running=true}updateTimerDock()}else if(a==='holdDone')holdStop(true);else if(a==='restPause'){if(rest.running){rest.remaining=Math.max(0,Math.ceil((rest.end-now())/1000));rest.running=false}else{rest.end=now()+rest.remaining*1000;rest.running=true}updateTimerDock()}else if(a==='restSkip')restStop();else if(a==='round'){let stage=id,max=stage==='Circuit'||stage==='Isometrics'?2:1;model.draft.rounds[stage]=Math.min(max,(model.draft.rounds[stage]||0)+1);save();render();note(`${stage}: round ${model.draft.rounds[stage]} recorded`)}else if(a==='pauseWorkout')tabTo('home');else if(a==='discard'){if(confirm('Discard your unfinished draft? Saved workouts will remain.')){model.draft=null;save();holdStop(false);restStop();tabTo('home')}}else if(a==='finish')finish();else if(a==='historyDetail'){ui.historyId=id;tabTo('historyDetail')}else if(a==='deleteHistory'){if(confirm('Delete this completed workout? This cannot be undone.')){model.sessions=model.sessions.filter(s=>s.id!==id);save();tabTo('history')}}else if(a==='backup')backup();else if(a==='csv')csv();else if(a==='saveAssessment'){let left=Number($('#ankle-left').value),right=Number($('#ankle-right').value);if(!$('#ankle-left').value||!$('#ankle-right').value||!Number.isFinite(left)||!Number.isFinite(right)||left<0||right<0||left>40||right>40){note('Enter knee-to-wall distances from 0 to 40 cm.');return}model.assessments.push({date:now(),left,right,hip:Number($('#hip-quality').value),shoulder:Number($('#shoulder-quality').value)});save();render();note('Mobility assessment saved.')}}

function extraClick(el){let a=el.dataset.act,id=el.dataset.id;if(a==='toggleCustomExercise'){let ids=ui.customSelected;ui.customSelected=ids.includes(id)?ids.filter(k=>k!==id):[...ids,id];const scroll=window.scrollY;render();window.scrollTo(0,scroll)}else if(a==='customClear'){ui.customSelected=[];render()}else if(a==='saveCustom')saveCustom();else if(a==='deleteCustom'){if(confirm('Delete custom workout? Completed sessions are kept.')){if(model.draft?.workout===id){note('Finish or discard this workout draft before deleting.');return}model.customWorkouts=model.customWorkouts.filter(w=>w.id!==id);model.prefs.rotationAddons=model.prefs.rotationAddons.filter(a=>a.id!==id);save();render()}}else if(a==='removeAddon'){model.prefs.rotationAddons=model.prefs.rotationAddons.filter(z=>z.id!==id);save();render();note('Removed from rotation; workout history retained.')}else if(a==='newCustom'){ui.editingCustom=null;ui.customSelected=[];ui.customName='My custom workout';ui.guideMuscle='all';ui.guideType='all';ui.guideSearch='';tabTo('custom')}else if(a==='editCustom'){let w=cleanCustom(id);if(!w)return;ui.editingCustom=id;ui.customSelected=w.exercises.map(x=>x.id);ui.customName=w.name;ui.guideMuscle='all';ui.guideType='all';ui.guideSearch='';tabTo('custom')}else if(a==='groupMode'){ui.guideMode=el.dataset.mode;ui.guideMuscle='all';ui.guideType='all';render()}else if(a==='groupPick'){if(ui.guideMode==='type')ui.guideType=el.dataset.group;else ui.guideMuscle=el.dataset.group;render()}else if(a==='monthChange'){ui.monthOffset+=Number(el.dataset.step);render()}else if(a==='calendarDay'){let day=Number(el.dataset.day),base=new Date(),first=new Date(base.getFullYear(),base.getMonth()+ui.monthOffset,1);let list=model.sessions.filter(s=>{let d=dateOf(s.date);return d.getFullYear()===first.getFullYear()&&d.getMonth()===first.getMonth()&&d.getDate()===day});let box=$('#calendar-details');if(box){box.innerHTML=`<h3>${day} ${first.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h3>`+(list.length?list.map(s=>`<button class="history-row" data-act="historyDetail" data-id="${safe(s.id)}"><span>${safe((s.workoutName||getWorkout(s.workout).name))} · ${totalSets(s)} sets</span>${icon('arrow')}</button>`).join(''):'<p>No workout recorded on this date.</p>');box.scrollIntoView({behavior:'smooth',block:'nearest'})}}else if(a==='progressTab'){ui.progressTab=el.dataset.tab;ui.progressPickerOpen=false;renderProgressAt('progress-controls')}else if(a==='toggleExercisePicker'){ui.progressPickerOpen=!ui.progressPickerOpen;renderProgressAt('strength-exercise-picker')}else if(a==='progressExercise'){ui.progressId=id;ui.progressPickerOpen=false;renderProgressAt('strength-exercise-picker')}else if(a==='progressPeriod'){ui.statPeriod=Number(el.dataset.days)||28;renderProgressAt('progress-controls')}else if(a==='showArt'){ui.guideId=id;lightbox()}else if(a==='closeArt')el.closest('dialog')?.close();else if(a==='numberClear'){if(entryModal){entryModal.value='';document.getElementById('number-display').textContent='0'}}else if(a==='testSound'){audioUnlock();beep('start');setTimeout(()=>beep('finish'),400)}else if(a==='guideSearch'||a==='builderSearch'){ui.guideSearch=(document.getElementById(a==='guideSearch'?'guide-search':'builder-search')?.value||ui.guideSearch||'').trim();render()}else if(a==='guidePrompt'||a==='builderPrompt'){let current=ui.guideSearch||'';let val=prompt('Type your search',current);if(val!==null){ui.guideSearch=val.trim();render();setTimeout(()=>{let target=document.getElementById(a==='guidePrompt'?'guide-search':'builder-search');if(target)target.value=ui.guideSearch},10)}}else if(a==='guideClear'||a==='builderClear'){ui.guideSearch='';render()}else if(a==='checkUpdate'){note('Checking for a new version…');Promise.resolve(navigator.serviceWorker?.getRegistration?.()).then(reg=>reg?.update?.()).catch(()=>{}).finally(()=>{location.assign('./?update='+Date.now())})}}

document.addEventListener('click',ev=>{let b=ev.target.closest('[data-page],[data-act],button[data-theme],button[data-color],[data-filter]');if(!b)return;if(b.dataset.theme){model.prefs.theme=b.dataset.theme;save();render();return}if(b.dataset.color){model.prefs.color=b.dataset.color;save();render();return}if(b.dataset.filter){ui.guideFilter=b.dataset.filter;render();return}doClick(b)});
document.addEventListener('input',ev=>{let el=ev.target;if(el.id==='custom-name'){ui.customName=el.value;return}if(el.id==='builder-search'){ui.guideSearch=el.value;return}if(el.dataset.entry){editEntry(el);return}if(el.id==='session-notes'&&model.draft){model.draft.notes=el.value;save()}else if(el.id==='guide-search'){ui.guideSearch=el.value}});
document.addEventListener('change',async ev=>{let el=ev.target;if(el.dataset.pref){model.prefs[el.dataset.pref]=Number(el.value);save();render()}else if(el.id==='volume-select'){model.prefs.volume=el.value;save();render()}else if(el.id==='sound-enabled'){model.prefs.sound=el.checked;save();render()}else if(el.name==='custom-mode'){ui.customReplace=el.value;render()}else if(el.id==='custom-target'){ui.customTarget=el.value;render()}else if(el.id==='builder-muscle'){ui.guideMuscle=el.value;render()}else if(el.id==='builder-type'){ui.guideType=el.value;render()}else if(el.id==='builder-search'||el.id==='guide-search'){render()}else if(el.id==='show-optional'){model.prefs.includeOptional=el.checked;save();render()}else if(el.id==='import-file'&&el.files?.[0]){try{let b=JSON.parse(await el.files[0].text()),state=b?.app==='my-strength'&&/^[23](?:\.\d+)*$/.test(String(b.version))?b.state:null;if(!state&&b.app==='my-strength'&&Array.isArray(b.sessions)){state=initial();state.sessions=b.sessions.map(s=>({...s,legacy:true}));state.migrated=true}if(!state||!Array.isArray(state.sessions)||!state.sessions.every(s=>s.entries&&typeof s.workout==='string'&&Number.isFinite(Number(s.date))))throw Error('Not a compatible backup');if(confirm(`Replace your current ${model.sessions.length} recorded workouts with ${state.sessions.length} from this backup?`)){model={...initial(),...state,prefs:{...initial().prefs,...state.prefs}};save();tabTo('home');note('Backup restored')}}catch(e){note('Import failed: '+e.message)}el.value=''}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&entryModal){numberEntryCommit(true)}if(ev.key==='Enter'&&(ev.target?.id==='guide-search'||ev.target?.id==='builder-search')){ev.preventDefault();render()}});
setInterval(()=>{if(rest.running){rest.remaining=Math.max(0,Math.ceil((rest.end-now())/1000));if(timerLast.rest!==rest.remaining){timerLast.rest=rest.remaining;if(rest.remaining===Math.ceil(Number(model.prefs.restSeconds)/2))beep('half');else if(rest.remaining>=1&&rest.remaining<=3)beep('last')}if(rest.remaining===0){beep('finish');restStop();note('Rest complete. Ready for the next set.')}else updateTimerDock()}if(hold.running){hold.remaining=Math.max(0,Math.ceil((hold.end-now())/1000));if(timerLast.hold!==hold.remaining){timerLast.hold=hold.remaining;if(hold.prep&&hold.remaining>=1)beep('tick');else if(!hold.prep&&hold.remaining===Math.ceil(hold.total/2))beep('half');else if(!hold.prep&&hold.remaining>=1&&hold.remaining<=3)beep('last')}if(hold.remaining===0){if(hold.prep){hold.prep=0;hold.started=now();hold.remaining=hold.total;hold.end=now()+hold.total*1000;timerLast.hold=null;beep('start');updateTimerDock()}else{const id=hold.id,i=hold.index;let z=model.draft?.entries?.[id]?.[i];if(z){z.seconds=String(hold.total);save();refreshEntry(id,i)}beep('finish');holdStop(false);note('Hold complete. Tap the set checkmark to confirm.')}}else updateTimerDock()}},180);

// AI beta: append the confirmed exercise to the real tracker draft, without
// changing the user's stored history or starting a duplicate test tracker.
function scanExerciseList(draft){
  const core=getWorkout(draft.workout).exercises;
  const added=(draft.scannedExercises||[]).map(id=>byId(id)).filter(x=>x&&!core.some(c=>c.id===x.id));
  return [...core,...added];
}
function addMachineExercise(exerciseId){
  if(!['pulldown','legpress','rowc','extension'].includes(exerciseId)){note('This exercise is not in the verified machine catalogue.');return false}
  const exercise=byId(exerciseId);
  if(!exercise){note('Exercise not present in this tracker version.');return false}
  if(!model.draft){
    const suggested=nextInfo().next;
    const workoutId=suggested?.id||'A';
    startWorkout(workoutId);
    if(!model.draft)return false;
  }
  const exists=scanExerciseList(model.draft).some(e=>e.id===exerciseId);
  if(!exists)model.draft.scannedExercises=[...(model.draft.scannedExercises||[]),exerciseId];
  if(!model.draft.entries[exerciseId])model.draft.entries[exerciseId]=setDefaults(exercise);
  save();
  ui.openWorkout=model.draft.workout;tabTo('active');
  setTimeout(()=>document.getElementById('ex-'+exerciseId)?.scrollIntoView({block:'start',behavior:'smooth'}),120);
  note(exists?'Exercise already in this workout.':'Machine exercise added to your workout.');
  return true;
}
window.MyStrengthAddMachine=addMachineExercise;

async function init(){let local=getJSON(KEY,null);try{db=await openDb();const stored=await idbRead();model=stored&&typeof stored==='object'?stored:(local&&typeof local==='object'?local:initial());if(local&&stored&&Array.isArray(local.sessions)&&local.sessions.length>stored.sessions.length)model=local;}catch{model=local&&typeof local==='object'?local:initial()}model.prefs={...initial().prefs,...model.prefs};model.prefs.rotationAddons=Array.isArray(model.prefs.rotationAddons)?model.prefs.rotationAddons:[];model.schema=3;model.sessions=Array.isArray(model.sessions)?model.sessions:[];model.assessments=Array.isArray(model.assessments)?model.assessments:[];model.customWorkouts=Array.isArray(model.customWorkouts)?model.customWorkouts:[];migrateLegacy();render();if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js?v=3.3.5-ai1').catch(()=>{});}
init();
